tool_input.command:
cat > src/pickList.test.ts <<'EOF'
import { describe, expect, test } from "bun:test";
import { buildPickList, OrderFormatError, type StockLot } from "./pickList";

/*
 * Test list:
 * [ ] empty text -> nothing
 * [ ] one order, one item, one covering lot -> one pick
 * [ ] no stock -> shortage
 * [ ] partial stock -> pick what is there plus shortage
 * [ ] lots by earliest expiry, null last, ties by bin
 * [ ] stock consumed by earlier orders
 * [ ] priority orders first, in text order
 * [ ] duplicate SKU in an order summed, first position kept
 * [ ] comments, empty lines, surrounding whitespace ignored
 * [ ] format errors (item before ORDER, duplicate id, empty order, bad lines, first from top)
 * [ ] serpentine walking order
 * [ ] picks at same bin keep allocation order
 * [ ] stock is not modified
 */

const lot = (bin: string, sku: string, qty: number, expires: string | null = null): StockLot => ({
  bin,
  sku,
  qty,
  expires,
});

test("format errors name the line", () => {
  const error = new OrderFormatError(7, "quantity must be positive");
  expect(error).toBeInstanceOf(Error);
  expect(error.line).toBe(7);
  expect(error.message).toBe("Line 7: quantity must be positive");
});

test("empty text yields an empty pick list", () => {
  expect(buildPickList("", [])).toEqual({ picks: [], shortages: [] });
});
EOF
bun test 2>&1 | tail -5

python3 - <<'EOF'
p='src/pickList.ts'
s=open(p).read()
s=s.replace('''export function buildPickList(_ordersText: string, _stock: StockLot[]): PickList {
  throw new Error("Not implemented");
}''','''export function buildPickList(_ordersText: string, _stock: StockLot[]): PickList {
  return { picks: [], shortages: [] };
}''')
open(p,'w').write(s)
EOF
bun test 2>&1 | tail -3 && git add -A && git commit -qm "Empty orders text yields empty pick list" && echo ok

cat >> src/pickList.test.ts <<'EOF'

test("a single item covered by a single lot yields one pick", () => {
  const result = buildPickList("ORDER 1001\n  OLIVE-500 x3", [lot("A-01-1", "OLIVE-500", 10)]);
  expect(result).toEqual({
    picks: [{ bin: "A-01-1", sku: "OLIVE-500", qty: 3, orderId: "1001" }],
    shortages: [],
  });
});
EOF
bun test 2>&1 | grep -E "pass|fail" | tail -2
